CREATE TABLE app_user(id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE training_class(id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, owner_id BIGINT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, FOREIGN KEY(owner_id) REFERENCES app_user(id));
CREATE TABLE teacher(id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL);
CREATE TABLE student(id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL);
CREATE TABLE enrollment(class_id BIGINT NOT NULL, student_id BIGINT NOT NULL, PRIMARY KEY(class_id,student_id), FOREIGN KEY(class_id) REFERENCES training_class(id), FOREIGN KEY(student_id) REFERENCES student(id));
CREATE TABLE lesson(id BIGINT AUTO_INCREMENT PRIMARY KEY, class_id BIGINT NOT NULL, teacher_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, taught_at TIMESTAMP NOT NULL, FOREIGN KEY(class_id) REFERENCES training_class(id), FOREIGN KEY(teacher_id) REFERENCES teacher(id));
CREATE TABLE evaluation_task(id BIGINT AUTO_INCREMENT PRIMARY KEY, lesson_id BIGINT NOT NULL, token VARCHAR(64) NOT NULL UNIQUE, status VARCHAR(20) NOT NULL, opens_at TIMESTAMP NOT NULL, closes_at TIMESTAMP NOT NULL, FOREIGN KEY(lesson_id) REFERENCES lesson(id));
-- 每个任务发布时快照应评名单；评价码由管理员私下发放，不在公共任务接口返回。
CREATE TABLE eligibility(id BIGINT AUTO_INCREMENT PRIMARY KEY, task_id BIGINT NOT NULL, student_id BIGINT NOT NULL, access_code VARCHAR(64) NOT NULL UNIQUE, UNIQUE(task_id,student_id), FOREIGN KEY(task_id) REFERENCES evaluation_task(id), FOREIGN KEY(student_id) REFERENCES student(id));
CREATE TABLE answer(id BIGINT AUTO_INCREMENT PRIMARY KEY, eligibility_id BIGINT NOT NULL UNIQUE, teaching INT NOT NULL, content INT NOT NULL, organization INT NOT NULL, comment VARCHAR(1000) NOT NULL, source VARCHAR(20) NOT NULL, operator_name VARCHAR(80), receipt VARCHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(eligibility_id) REFERENCES eligibility(id));
